 96 │ /**
 97 │  * The backup ref of a branch: `refs/nexus-backup/<readable name>-<12 hex of sha1(branch)>`. One flat component, so
 98 │  * `foo` and `foo/bar` (which Git cannot hold as refs side by side) never collide, and the hash keeps names that
 99 │  * sanitise alike apart. List them with `git for-each-ref refs/nexus-backup`.
100 │  */
101 │ export function backupRef(branch: string): string {
102 │   const readable = branch.replace(/[^A-Za-z0-9._-]+/g, "-").replace(/^[.-]+/, "").slice(0, 40) || "branch";
103 │   return `refs/nexus-backup/${readable}-${createHash("sha1").update(branch).digest("hex").slice(0, 12)}`;
104 │ }
