106 │ /** A commit holding the worktree exactly as `git add -A` would see it, stored at backupRef(branch). */
107 │ function backup(dir: string, branch: string, dirty: boolean): string {
108 │   let sha = gitOut(dir, ["rev-parse", "--verify", "HEAD"]);
109 │   if (dirty) {
110 │     const tree = workingState(dir, dirty).tree;
111 │     sha = gitOut(dir, ["commit-tree", tree, "-p", sha, "-m", `nexus backup of ${branch} before merge`]);
112 │   }
113 │   git(dir, ["update-ref", "-m", "nexus: backup before merge", backupRef(branch), sha]);
114 │   return sha;
115 │ }
