131 │ /**
132 │  * Whether this merge will write a commit message at all, so a caller that has to produce one (the model) asks only
133 │  * when it is used: uncommitted changes are committed; a clean branch is squashed (more than one commit) or, on the
134 │  * model path, its lone commit is amended; commits that cancel each other out merge as a no-op and need no message.
135 │  */
136 │ export function writesCommitMessage(mctx: MergeContextInfo, options: MergeOptions): boolean {
137 │   if (mctx.state.total > 0) return true;
138 │   if (mctx.ahead === 0) return false;
139 │   const tree = (rev: string) => gitOut(mctx.source.path, ["rev-parse", "--verify", "--end-of-options", `${rev}^{tree}`]);
140 │   if (tree("HEAD") === tree(mctx.mergeBase)) return false; // cancelled
141 │   return (mctx.ahead > 1 && !options.noSquash) || (mctx.ahead === 1 && options.amendSingleCommit === true);
142 │ }
