166 │   const busy = inProgress(gitDir);
167 │   if (busy) throw new WorktreeError(`a ${busy.op} is already in progress in this worktree; finish it (${busy.cmd}) and run merge again`);
168 │   const targetState = statusOf(targetEntry.path);
169 │   if (targetState.total > 0) throw new WorktreeError(`the target worktree (${shownBranch(targetName)}) has uncommitted changes; commit or stash them first`);
