390	390 │   const here = currentEntry(repo);
391	391 │   const target = defaultBranch(repo);
392	392 │   const targetSha = target ? resolveBranchCommit(repo, target) : undefined;
393	393 │   if (!targetSha) throw new WorktreeError("this repository has no default branch to compare against");
394	394 │ 
395	395 │   const lines: string[] = [];
396	396 │   const counts = { removed: 0, kept: 0, young: 0, stale: 0 };
397	397 │   let limited = false;
398	398 │   const label = (entry: WorktreeEntry) => (entry.branch ? shownBranch(entry.branch) : shownPath(ctx.home, entry.path));
399	399 │   const keep = (entry: WorktreeEntry, why: string) => { counts.kept++; lines.push(`kept ${label(entry)}: ${why}`); };
400	400 │   const now = Date.now();
401	401 │ 
402	402 │   for (const entry of repo.entries) {
403	403 │     if (entry.isMain || entry === here) continue;
404	404 │     if (counts.removed >= limit) { limited = true; break; }
405	405 │     if (entry.prunable && entry.locked) { keep(entry, "stale but locked"); continue; }
406	406 │     if (entry.prunable) {
407	407 │       // A hand-deleted worktree is judged like any other. A detached one may hold the only reference to commits in its
408	408 │       // administrative HEAD and reflog, so it goes only if that HEAD is integrated and old enough; a branch worktree's
409	409 │       // commits live on its branch, which stays. Only the selected entries are cleared, never a global `worktree prune`.
410	410 │       try {
411	411 │         const stamp = Number(gitOut(repo.cwd, ["log", "-1", "--format=%ct", "--end-of-options", entry.head], { timeoutMs: 5000 })) * 1000;
412	412 │         if (entry.detached && now - stamp < minAge) { counts.young++; continue; }
413	413 │         const reason = entry.detached ? integratedReason(repo, entry.head, targetSha) : "branch kept";
414	414 │         if (!reason) { keep(entry, `stale, but its detached HEAD is not merged into ${shownBranch(target!)}`); continue; }
415	415 │         if (!options.dryRun) clearStaleEntry(repo, entry);
416	416 │         counts.stale++;
417	417 │         counts.removed++;
418	418 │         lines.push(`${options.dryRun ? "would clear" : "cleared"} stale ${label(entry)} (${reason})`);
419	419 │       } catch (err) {
420	420 │         keep(entry, redactSecrets((err as Error).message).slice(0, 160));
421	421 │       }
422	422 │       continue;
423	423 │     }
424	424 │     if (entry.locked) { keep(entry, "locked"); continue; }
425	425 │     if (isSpeculativeEntry(repo, entry)) { keep(entry, "speculative task worktree"); continue; }
426	426 │     try {
427	427 │       const touched = Math.max(fs.statSync(entry.path).mtimeMs, Number(gitOut(repo.cwd, ["log", "-1", "--format=%ct", "--end-of-options", entry.head], { timeoutMs: 5000 })) * 1000);
428	428 │       if (now - touched < minAge) { counts.young++; continue; }
429	429 │       const reason = integratedReason(repo, entry.head, targetSha);
430	430 │       if (!reason) { keep(entry, `not merged into ${shownBranch(target!)}`); continue; }
431	431 │       const dirty = statusOf(entry.path, { ignored: true, ignoreSubmodules: "none" });
432	432 │       if (dirty.total > 0) { keep(entry, `dirty (${dirty.staged + dirty.modified} changed, ${dirty.untracked} untracked)`); continue; }
433	433 │       if (dirty.ignored > 0 && !options.discardIgnored) { keep(entry, `${dirty.ignored} ignored path(s); pass --discard-ignored to prune it anyway`); continue; }
434	434 │       if (options.dryRun) {
435	435 │         counts.removed++;
436	436 │         lines.push(`would remove ${label(entry)} (integrated: ${reason})`);
437	437 │         continue;
438	438 │       }
439	439 │       removeOne(ctx, entry.path, { discardIgnored: dirty.ignored > 0 });
440	440 │       counts.removed++;
441	441 │       lines.push(`removed ${label(entry)} (integrated: ${reason})`);
442	442 │     } catch (err) {
443	443 │       keep(entry, redactSecrets((err as Error).message).slice(0, 160));
444	444 │     }
445	445 │   }
446	446 │ 
447	447 │   const summary = `${options.dryRun ? "Would remove" : "Removed"} ${counts.removed}, kept ${counts.kept}, ${counts.young} younger than the minimum age${counts.stale ? `, ${counts.stale} stale registration(s) ${options.dryRun ? "would be pruned" : "pruned"}` : ""}.`;
448	448 │   const shown = lines.slice(0, REPORT_LINES);
449	449 │   if (lines.length > REPORT_LINES) shown.push(`... ${lines.length - REPORT_LINES} more lines`);
450	450 │   if (limited) shown.push(`stopped at the limit of ${limit} removals; run prune again for more`);
451	451 │   return { success: true, output: [...shown, summary].join("\n"), data: { ...counts, limited } };
452	452 │ }
