  1 │ /**
  2 │  * Verification records for named-worktree merges.
  3 │  *
  4 │  * A CLI merge has no in-memory agent receipt, so the agent run (or any verifier Nexus ran and saw pass) records
  5 │  * `branch + head + tree` in the registry. The tree is that of the working state at the time (HEAD plus uncommitted
  6 │  * work, as `git add -A` would commit it), so a later edit or commit no longer matches. Running a project verifier is
  7 │  * not done here: that stays under the approval model of WP-1313.
  8 │  */
  9 │ import * as fs from "node:fs";
 10 │ import * as os from "node:os";
 11 │ import * as path from "node:path";
 12 │ import { redactSecrets } from "../ui.js";
 13 │ import { statusOf } from "./core.js";
 14 │ import { git, gitOut, nestedRepositoryReason, parseSubmoduleStatus } from "./git.js";
 15 │ import { MAX_BRANCH_LENGTH, MAX_RECORDS, updateRegistry, type Registry } from "./registry.js";
 16 │ import { currentEntry, openRepo } from "./repo.js";
 17 │ 
 18 │ /** Pathspec of `.nexus/` (sessions, knowledge, worktrees): unstaged after `add -A` so it never reaches a backup, a receipt or an automatic commit. */
 19 │ export const NEXUS_STATE_PATH = ":(top).nexus";
 20 │ 
 21 │ export interface WorkingState { head: string; tree: string; dirty: boolean }
 22 │ 
 23 │ /**
 24 │  * Configuration and index flags that make Git skip or misread a modification, overridden for the strict snapshot:
 25 │  * stat caching (`core.ignoreStat`), the executable bit (`core.fileMode`), symlinks, sparse checkout and the untracked
 26 │  * cache. Content conversion (`core.autocrlf`, filters, `.gitattributes`) is left alone: a merge's own `git add -A`
 27 │  * applies it too, so both sides agree on what the bytes become.
 28 │  */
 29 │ const STRICT_CONFIG = [
 30 │   "-c", "core.ignoreStat=false", "-c", "core.sparseCheckout=false", "-c", "core.sparseCheckoutCone=false",
 31 │   "-c", "core.untrackedCache=false", "-c", "core.splitIndex=false", "-c", "status.showUntrackedFiles=all",
 32 │ ];
 33 │ 
 34 │ /** Whether the filesystem under `gitDir` stores executable bits and symlinks; where it does not, Git sets `core.fileMode`/`core.symlinks` false for a reason and forcing them would turn every file into a change. */
 35 │ function filesystemCapabilities(gitDir: string): { modes: boolean; symlinks: boolean } {
 36 │   const probe = fs.mkdtempSync(path.join(gitDir, "nexus-probe-"));
 37 │   try {
 38 │     let modes = false;
 39 │     let symlinks = false;
 40 │     try {
 41 │       const file = path.join(probe, "f");
 42 │       fs.writeFileSync(file, "x");
 43 │       fs.chmodSync(file, 0o755);
 44 │       modes = (fs.statSync(file).mode & 0o111) !== 0;
 45 │     } catch { /* no exec bits */ }
 46 │     try { fs.symlinkSync("f", path.join(probe, "l")); symlinks = true; } catch { /* no symlinks */ }
 47 │     return { modes, symlinks };
 48 │   } finally {
 49 │     fs.rmSync(probe, { recursive: true, force: true });
 50 │   }
 51 │ }
 52 │ 
 53 │ /**
 54 │  * The tree `git add -A` would commit (minus `.nexus`), via a temporary index. `fresh`: the index starts as
 55 │  * `read-tree HEAD` with the strict configuration, so nothing the repository's index or configuration says (an
 56 │  * `--assume-unchanged` or `--skip-worktree` flag, a stale stat entry, `core.fileMode=false`, a sparse checkout) can
 57 │  * hide an edit: every file is compared with HEAD by content and mode. Otherwise the user's own index is the start,
 58 │  * which is what a merge's `add -A` uses.
 59 │  */
 60 │ function snapshotTree(dir: string, fresh: boolean): string {
 61 │   const scratch = fs.mkdtempSync(path.join(os.tmpdir(), "nexus-tree-"));
 62 │   try {
 63 │     const env = { GIT_INDEX_FILE: path.join(scratch, "index") };
 64 │     const gitDir = gitOut(dir, ["rev-parse", "--path-format=absolute", "--git-dir"]);
 65 │     const realIndex = path.join(gitDir, "index");
 66 │     const config = [...(fresh ? STRICT_CONFIG : [])];
 67 │     if (fresh) {
 68 │       const capabilities = filesystemCapabilities(gitDir);
 69 │       if (capabilities.modes) config.push("-c", "core.fileMode=true");
 70 │       if (capabilities.symlinks) config.push("-c", "core.symlinks=true");
 71 │     }
 72 │     if (!fresh && fs.existsSync(realIndex)) {
 73 │       fs.copyFileSync(realIndex, path.join(scratch, "index"));
 74 │     } else {
 75 │       git(dir, [...config, "read-tree", "HEAD"], { env });
 76 │     }
 77 │     if (fresh) carryIndexIntentions(dir, config, env);
 78 │     git(dir, [...config, "add", "-A"], { env });
 79 │     git(dir, ["reset", "-q", "HEAD", "--", NEXUS_STATE_PATH], { env, allowFailure: true }); // internal state is never part of a merge
 80 │     return gitOut(dir, ["write-tree"], { env });
 81 │   } finally {
 82 │     fs.rmSync(scratch, { recursive: true, force: true });
 83 │   }
 84 │ }
 85 │ 
 86 │ /**
 87 │  * What the repository's own index legitimately says and a merge's `add -A` honours, carried into the fresh index:
 88 │  * a skip-worktree entry that is simply not on disk (sparse checkout) is not a deletion, and a new file the operator
 89 │  * staged on purpose with `add -f` stays even though it is ignored. A skip-worktree file that IS on disk is not
 90 │  * carried: an edit to it must be seen.
 91 │  */
 92 │ function carryIndexIntentions(dir: string, config: string[], env: Record<string, string>): void {
 93 │   const absentSparse: string[] = [];
 94 │   for (const entry of gitOut(dir, ["ls-files", "-v", "-z"]).split("\0")) {
 95 │     if (!/^[Ss] /.test(entry)) continue;
 96 │     const file = entry.slice(2);
 97 │     try { fs.lstatSync(path.join(dir, file)); } catch { absentSparse.push(file); }
 98 │   }
 99 │   if (absentSparse.length > 0) {
100 │     git(dir, [...config, "update-index", "--skip-worktree", "-z", "--stdin"], { env, input: absentSparse.join("\0") + "\0" });
101 │   }
102 │   const staged = gitOut(dir, ["diff-index", "--cached", "--name-only", "--diff-filter=A", "-z", "HEAD"]).split("\0").filter(Boolean)
103 │     .filter((file) => { try { fs.lstatSync(path.join(dir, file)); return true; } catch { return false; } });
104 │   if (staged.length > 0) {
105 │     git(dir, [...config, "add", "-f", "--pathspec-from-file=-", "--pathspec-file-nul"], { env: { ...env, GIT_LITERAL_PATHSPECS: "1" }, input: staged.join("\0") + "\0" });
106 │   }
107 │ }
