109 │ /** HEAD, and the tree of the working state: HEAD^{tree} when clean, else a snapshot via a temporary index. */
110 │ export function workingState(dir: string, dirty: boolean): WorkingState {
111 │   const head = gitOut(dir, ["rev-parse", "--verify", "HEAD"]);
112 │   if (!dirty) return { head, tree: gitOut(dir, ["rev-parse", "--verify", "HEAD^{tree}"]), dirty };
113 │   return { head, tree: snapshotTree(dir, false), dirty };
114 │ }
115 │ 
116 │ /**
117 │  * Whether any initialised submodule of `dir`, nested ones included, holds uncommitted content (changes or untracked
118 │  * files), judged by the strict snapshot. The tree of the working state records only the submodule's gitlink, so such
119 │  * content would be tested by a verifier yet never be part of what a receipt authorises and a merge carries.
120 │  */
121 │ export function hasDirtySubmodule(dir: string): boolean {
122 │   for (const { path: rel, initialised } of parseSubmoduleStatus(gitOut(dir, ["submodule", "status", "--recursive"]))) {
123 │     if (!initialised) continue; // no content to differ
124 │     const sub = path.join(dir, rel);
125 │     if (snapshotTree(sub, true) !== gitOut(sub, ["rev-parse", "--verify", "HEAD^{tree}"])) return true;
126 │   }
127 │   return false;
128 │ }
129 │ 
130 │ /**
131 │  * The working state of `dir` for a receipt, or undefined when it cannot be certified: a submodule holds uncommitted
132 │  * content, or the strict snapshot (see `snapshotTree`) differs from the state a merge would commit, meaning something
133 │  * in the repository's index or configuration hides an edit from `status` and `add -A`. Whatever a verifier saw, the
134 │  * receipt must cover exactly what a merge carries.
135 │  */
136 │ function certifiableState(dir: string): WorkingState | undefined {
137 │   if (nestedRepositoryReason(dir) !== undefined) return undefined; // before any Git runs inside a submodule below
138 │   if (hasDirtySubmodule(dir)) return undefined;
139 │   const state = workingState(dir, statusOf(dir).total > 0);
140 │   return snapshotTree(dir, true) === state.tree ? state : undefined;
141 │ }
142 │ 
143 │ /** The linked worktree containing `workspace` and its working state, or undefined (main checkout, detached, not a repository). Never throws. */
144 │ export function captureVerificationState(workspace: string): WorkingState | undefined {
145 │   try {
146 │     const entry = currentEntry(openRepo(workspace));
147 │     if (!entry || entry.isMain || !entry.branch) return undefined;
148 │     return certifiableState(entry.path);
149 │   } catch {
150 │     return undefined;
151 │   }
152 │ }
153 │ 
154 │ /**
155 │  * Records that `verifier` passed on the current state of the linked worktree containing `workspace`. With `expected`
156 │  * (the state captured before the verifier started) nothing is recorded if the working state is no longer that state:
157 │  * an edit made while the verifier ran was not tested. Never throws.
158 │  */
159 │ export function recordVerification(workspace: string, verifier: string, expected?: WorkingState): boolean {
160 │   try {
161 │     const repo = openRepo(workspace);
162 │     const entry = currentEntry(repo);
163 │     if (!entry || entry.isMain || !entry.branch || entry.branch.length > MAX_BRANCH_LENGTH) return false;
164 │     const state = certifiableState(entry.path);
165 │     if (!state) return false;
166 │     if (expected && (expected.head !== state.head || expected.tree !== state.tree)) return false;
167 │     const branch = entry.branch;
168 │     updateRegistry(repo.commonDir, (reg) => {
169 │       const list = (reg.verifications ?? []).filter((item) => !(item.branch === branch && item.tree === state.tree && item.head === state.head));
170 │       list.push({ branch, head: state.head, tree: state.tree, verifier: redactSecrets(verifier).slice(0, 200) || "verifier", recordedAt: new Date().toISOString() });
171 │       reg.verifications = list.slice(-MAX_RECORDS);
172 │     });
173 │     return true;
174 │   } catch {
175 │     return false;
176 │   }
177 │ }
178 │ 
179 │ export interface RecordRequest {
180 │   unrecordableWorktree: boolean;
181 │   dryRun: boolean;
182 │   verifierSucceeded: boolean;
183 │   hasExecuted: boolean;
184 │   deliverableBound: boolean;
185 │   /** The verifier is the configured authoritative one or an independent one (never a discovered generic command). */
186 │   verified: boolean;
187 │   verifier: string;
188 │   /** The working state captured before the verifier ran. */
189 │   before?: WorkingState;
190 │ }
191 │ 
192 │ /** The agent's recording step: a receipt only for a passing, deliverable-bound, configured-or-independent run on the state that was tested. */
193 │ export function recordVerificationIfEligible(workspace: string, request: RecordRequest): boolean {
194 │   if (request.unrecordableWorktree || request.dryRun || !request.verifierSucceeded || !request.hasExecuted || !request.deliverableBound || !request.verified) return false;
195 │   if (!request.before) return false;
196 │   return recordVerification(workspace, request.verifier, request.before);
197 │ }
198 │ 
199 │ /** Whether the registry holds a verification matching this exact state (head when clean, tree when dirty). */
200 │ export function hasVerification(registry: Registry, branch: string, state: WorkingState): boolean {
201 │   return (registry.verifications ?? []).some((item) => item.branch === branch && item.tree === state.tree && (state.dirty || item.head === state.head));
202 │ }

